SELECT * FROM `article` WHERE status = 1

    AND category = #{category}

ORDER BY is_top DESC, created_at DESC
LIMIT #{offset}, #{size}

mapper.update:
UPDATE `article` SET title = #{title}, summary = #{summary}, content = #{content},
    cover_image = #{coverImage}, category = #{category}, updated_at = NOW()
WHERE id = #{id}
